package in.industrend.social;import jakarta.servlet.http.HttpServletRequest;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/social") class SocialMediaController{record GenerateRequest(String prompt,String caption){}record PublishRequest(String caption){}private final SocialMediaService service;private final AdminAuthorizer auth;SocialMediaController(SocialMediaService service,AdminAuthorizer auth){this.service=service;this.auth=auth;}@PostMapping("/images")SocialMediaService.Post generate(@RequestBody GenerateRequest body,HttpServletRequest request){return service.create(body.prompt(),body.caption(),auth.require(request.getCookies()));}@GetMapping("/images/{id}")SocialMediaService.Post status(@PathVariable UUID id,HttpServletRequest request){auth.require(request.getCookies());return service.get(id);}@GetMapping("/images/{id}/content")ResponseEntity<byte[]>content(@PathVariable UUID id,HttpServletRequest request){auth.require(request.getCookies());return ResponseEntity.ok().contentType(MediaType.IMAGE_PNG).cacheControl(CacheControl.noStore()).body(service.image(id));}@PostMapping("/images/{id}/review")SocialMediaService.Post review(@PathVariable UUID id,HttpServletRequest request){auth.require(request.getCookies());return service.review(id);}@PostMapping("/images/{id}/publish")SocialMediaService.Post publish(@PathVariable UUID id,@RequestBody PublishRequest body,HttpServletRequest request){auth.require(request.getCookies());return service.publish(id,body.caption());}}
